// Paper image-dithering math, Apache-2.0. See design/paper-shaders-{LICENSE,NOTICE}.txt.
// The embedded image lets the local file preview use WebGL without file-origin texture errors.
(() => {
  [[".visual-container","data:image/webp;base64,"],[".examples-stage","data:image/webp;base64,"],[".check-scene[data-check=\"levels\"]","data:image/webp;base64,"],[".check-scene[data-check=\"options\"]","data:image/webp;base64,"],[".check-scene[data-check=\"indicators\"]","data:image/webp;base64,"]].forEach(([selector, imageUrl]) => {
  const stage = document.querySelector(selector);
  if (!stage) return;
  const sectionTwo = selector === '.examples-stage';
  const checkScene = selector.startsWith('.check-scene');
  const startSize = sectionTwo ? 6 : 10;
  const settledSize = sectionTwo ? 2 : 4;
  const startScale = 1.08;
  let replay;
  let reset;
  let pendingReplay = false;
  const onReplay = () => { if (replay) replay(); else pendingReplay = true; };
  const onReset = () => { pendingReplay = false; reset?.(); };
  stage.addEventListener('dither-replay', onReplay);
  stage.addEventListener('dither-reset', onReset);
  const source = new Image();
  source.onload = () => {
    const observer = new IntersectionObserver((entries) => {
      if (entries.some(entry => entry.isIntersecting)) {
        observer.disconnect();
        start(source);
      }
    }, { threshold: 0.1 });
    observer.observe(stage);
  };
  source.src = imageUrl;

  function start(image) {
    const canvas = document.createElement('canvas');
    canvas.className = 'dither-canvas';
    canvas.setAttribute('aria-hidden', 'true');
    const gl = canvas.getContext('webgl2', { alpha: false, antialias: false, depth: false, stencil: false });
    if (!gl) return;
    let frame = 0;
    let resizeObserver;
    const motion = matchMedia('(prefers-reduced-motion: reduce)');
    const alreadySettled = (sectionTwo && stage.dataset.sceneActive === 'true') ||
      (checkScene && stage.dataset.revealed === 'true' && stage.dataset.animate !== 'true');
    let currentSize = motion.matches || alreadySettled ? settledSize : startSize;
    let currentScale = currentSize === settledSize ? 1 : startScale;
    let ratio = 1;
    let coverWidth = 1;
    try {
      function shader(type, code) {
        const result = gl.createShader(type);
        gl.shaderSource(result, code);
        gl.compileShader(result);
        if (!gl.getShaderParameter(result, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(result));
        return result;
      }
      const vertex = shader(gl.VERTEX_SHADER, `#version 300 es
        in vec2 position;
        void main() { gl_Position = vec4(position, 0.0, 1.0); }
      `);
      const fragment = shader(gl.FRAGMENT_SHADER, `#version 300 es
        precision highp float;
        uniform sampler2D image;
        uniform vec2 resolution;
        uniform float imageAspect;
        uniform float pixelSize;
        uniform float imagePositionY;
        uniform float imageScale;
        out vec4 color;
        const int bayer[64] = int[64](
          0,32,8,40,2,34,10,42,48,16,56,24,50,18,58,26,
          12,44,4,36,14,46,6,38,60,28,52,20,62,30,54,22,
          3,35,11,43,1,33,9,41,51,19,59,27,49,17,57,25,
          15,47,7,39,13,45,5,37,63,31,55,23,61,29,53,21
        );
        void main() {
          vec2 grid = (gl_FragCoord.xy - 0.5 * resolution) / pixelSize;
          vec2 sampled = (floor(grid) + 0.5) * pixelSize;
          float coverWidth = max(resolution.x / imageAspect, resolution.y) * imageAspect;
          vec2 uv = vec2(sampled.x / coverWidth + 0.5, 0.5 - sampled.y / (coverWidth / imageAspect));
          uv.y += (imagePositionY - 0.5) * (1.0 - resolution.y / (coverWidth / imageAspect));
          uv = (uv - 0.5) / imageScale + 0.5;
          vec3 rgb = texture(image, uv).rgb;
          float lum = dot(rgb, vec3(0.2126, 0.7152, 0.0722));
          ivec2 cell = ivec2(mod(floor(grid), 8.0));
          float noise = float(bayer[cell.y * 8 + cell.x]) / 64.0 - 0.5;
          float quantized = floor(clamp(lum + noise / 4.0, 0.0, 1.0) * 4.0 + 0.5) / 4.0;
          vec3 dithered = rgb / max(lum, 0.001) * quantized;
          color = vec4(dithered, 1.0);
        }
      `);
      const program = gl.createProgram();
      gl.attachShader(program, vertex);
      gl.attachShader(program, fragment);
      gl.linkProgram(program);
      if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
      gl.useProgram(program);
      gl.deleteShader(vertex);
      gl.deleteShader(fragment);
      const buffer = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
      const position = gl.getAttribLocation(program, 'position');
      gl.enableVertexAttribArray(position);
      gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
      const texture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, image);
      gl.uniform1i(gl.getUniformLocation(program, 'image'), 0);
      gl.uniform1f(gl.getUniformLocation(program, 'imageAspect'), image.naturalWidth / image.naturalHeight);
      gl.uniform1f(gl.getUniformLocation(program, 'imagePositionY'), 0.5);
      const resolution = gl.getUniformLocation(program, 'resolution');
      const size = gl.getUniformLocation(program, 'pixelSize');
      const scale = gl.getUniformLocation(program, 'imageScale');

      function draw() {
        gl.uniform1f(size, currentSize * ratio);
        gl.uniform1f(scale, currentScale);
        gl.drawArrays(gl.TRIANGLES, 0, 3);
        stage.style.backgroundSize = `${coverWidth * currentScale}px auto`;
        canvas.dataset.gridSize = currentSize.toFixed(2);
        canvas.dataset.imageScale = currentScale.toFixed(3);
      }
      function resize() {
        const rect = stage.getBoundingClientRect();
        coverWidth = Math.max(rect.width, rect.height * image.naturalWidth / image.naturalHeight);
        ratio = Math.min(devicePixelRatio || 1, 2, Math.sqrt(1250000 / (rect.width * rect.height)));
        canvas.width = Math.max(1, Math.round(rect.width * ratio));
        canvas.height = Math.max(1, Math.round(rect.height * ratio));
        gl.viewport(0, 0, canvas.width, canvas.height);
        gl.uniform2f(resolution, canvas.width, canvas.height);
        draw();
      }
      stage.append(canvas);
      resize();
      if (gl.getError() !== gl.NO_ERROR) throw new Error('Dither rendering unavailable');
      stage.dataset.ditherReady = 'true';
      resizeObserver = new ResizeObserver(resize);
      resizeObserver.observe(stage);
      reset = () => {
        cancelAnimationFrame(frame);
        currentSize = motion.matches ? settledSize : startSize;
        currentScale = motion.matches ? 1 : startScale;
        draw();
        stage.dataset.ditherState = motion.matches ? 'complete' : 'ready';
      };
      replay = () => {
        cancelAnimationFrame(frame);
        stage.dataset.ditherRun = String(Number(stage.dataset.ditherRun || 0) + 1);
        currentSize = motion.matches ? settledSize : startSize;
        currentScale = motion.matches ? 1 : startScale;
        draw();
        stage.dataset.ditherState = motion.matches ? 'complete' : 'animating';
        if (motion.matches) return;
        let startedAt;
        function tick(now) {
          startedAt ??= now;
          const progress = Math.min((now - startedAt) / 250, 1);
          currentSize = startSize + (settledSize - startSize) * progress;
          currentScale = startScale + (1 - startScale) * progress;
          draw();
          if (progress < 1) frame = requestAnimationFrame(tick);
          else stage.dataset.ditherState = 'complete';
        }
        frame = requestAnimationFrame(tick);
      };
      const heroIsHome = !sectionTwo && !checkScene && document.querySelector('.examples-stage')?.dataset.sceneActive !== 'true';
      if (heroIsHome || pendingReplay || (checkScene && stage.dataset.animate === 'true')) replay();
      else stage.dataset.ditherState = currentSize === settledSize ? 'complete' : 'ready';
      pendingReplay = false;
      motion.addEventListener('change', event => {
        if (event.matches) replay();
      });
      canvas.addEventListener('webglcontextlost', event => {
        event.preventDefault();
        cancelAnimationFrame(frame);
        resizeObserver.disconnect();
        stage.removeEventListener('dither-replay', onReplay);
        stage.removeEventListener('dither-reset', onReset);
        delete stage.dataset.ditherReady;
        stage.style.backgroundSize = '';
        canvas.remove();
      });
    } catch (error) {
      cancelAnimationFrame(frame);
      resizeObserver?.disconnect();
      stage.removeEventListener('dither-replay', onReplay);
      stage.removeEventListener('dither-reset', onReset);
      delete stage.dataset.ditherReady;
      stage.style.backgroundSize = '';
      canvas.remove();
      console.warn('Using static dither background:', error.message);
    }
  }
  });
})();
